const rows = $input.all();
const cfg = {};
for (const it of rows) {
  const k = it.json.setting !== undefined ? it.json.setting : it.json.key;
  if (k === undefined || k === null || String(k).trim() === '') continue;
  cfg[String(k).trim()] = it.json.value;
}
cfg.OWNER_NAME = 'Shradha';
cfg.SENDER_NAME = 'Shradha';
return [{ json: cfg }];

const staticData = $getWorkflowStaticData('global');
staticData.contactedThisRun = [];
staticData.runLog = [];
return $('Read PIPELINE').all();

const cfg = $('Build CONFIG object').first().json;
const OWNER = cfg.OWNER_NAME;
const VALID_OWNERS = Object.keys(cfg).filter((k) => /^OWNER_[A-Z]$/.test(k)).map((k) => String(cfg[k]).trim()).filter((v) => v !== '');
const tz = cfg.TIMEZONE || 'Asia/Kolkata';
const nowTz = DateTime.now().setZone(tz);
const today = nowTz.toISODate();
const todayWeekday = nowTz.toFormat('cccc');
const rotateBySendDay = String(cfg.ROTATE_BY_SEND_DAY || '').trim().toLowerCase() === 'yes';

const startupByName = {};
for (const s of $('Read STARTUPS').all()) { startupByName[String(s.json.startup).trim()] = s.json; }
const investorByName = {};
for (const v of $('Read INVESTORS').all()) { investorByName[String(v.json.investor).trim()] = v.json; }

const blank = (x) => x === undefined || x === null || String(x).trim() === '';
const isYes = (x) => String(x).trim().toLowerCase() === 'yes';
const num = (x) => { const n = parseFloat(String(x).replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
const isoRe = /^\d{4}-\d{2}-\d{2}$/;
const parseDue = (x) => {
  if (blank(x)) return { ok: true, val: null };
  const str = String(x).trim();
  if (!isoRe.test(str)) return { ok: false, val: null };
  const d = DateTime.fromISO(str, { zone: tz });
  if (!d.isValid) return { ok: false, val: null };
  return { ok: true, val: str };
};
const due = (val) => val !== null && val <= today;

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const base = {
    deal_id: r.deal_id, startup: r.startup, investor: r.investor, owner: r.owner,
    email: r.email, cc: r.cc, thread_id: r.thread_id, message_id: r.message_id, channel: r.channel,
  };
  const push = (action, reason, stage) => out.push({ json: Object.assign({}, base, { action, reason, stage: stage || '' }) });

  const ownerVal = String(r.owner || '').trim();
  if (ownerVal === '' || VALID_OWNERS.indexOf(ownerVal) === -1) { push('error', "OWNER_INVALID: owner '" + ownerVal + "' not found in CONFIG", ''); continue; }
  if (ownerVal !== OWNER) { push('skip', 'not-my-owner', ''); continue; }

  if (!blank(r.pause)) { push('skip', 'row-paused', ''); continue; }
  if (!blank(r.investor_response)) { push('skip', 'investor_response-set', ''); continue; }
  if (!blank(r.deal_status) && String(r.deal_status).trim().toLowerCase() !== 'open') { push('skip', 'deal_status-not-open', ''); continue; }
  if (isYes(r.meeting_scheduled) || !blank(r.meeting_date) || num(r.meetings_held) > 0 || !blank(r.last_meeting_date) || !blank(r.meeting_outcome) || num(r.committed_cr) > 0) {
    push('skip', 'meeting-stage', ''); continue;
  }
  const inv = investorByName[String(r.investor).trim()];
  if (!inv) { push('error', 'investor-not-found', ''); continue; }
  if (isYes(inv.do_not_contact)) { push('skip', 'do-not-contact', ''); continue; }
  const st = startupByName[String(r.startup).trim()];
  if (!st) { push('error', 'startup-not-found', ''); continue; }
  if (!isYes(st.active)) { push('error', 'startup-not-active', ''); continue; }
  if (blank(r.email)) { push('error', 'email-missing', ''); continue; }
  const varsMissing = blank(st.highlight_1) || blank(st.highlight_2) || blank(st.highlight_3) || blank(st.deck_link) || blank(st.sector) || blank(st.raise_inr_cr) || blank(inv.contact_person) || blank(inv.investor) || blank(st.memo_html);
  if (varsMissing) { push('error', 'template-var-missing', ''); continue; }

  if (!isYes(r.deal_shared)) {
    const pd = parseDue(r.next_due);
    if (!pd.ok) { push('error', 'DATE_PARSE_FAILED', ''); continue; }
    if (!pd.val) { push('error', 'NEXT_DUE_MISSING', ''); continue; }
    if (!due(pd.val)) { push('skip', 'initial-not-due', ''); continue; }
    if (rotateBySendDay && String(st.send_day).trim().toLowerCase() !== todayWeekday.toLowerCase()) {
      push('skip', 'rotation-not-today', ''); continue;
    }
    push('send', 'initial', 'INITIAL'); continue;
  }
  const pd = parseDue(r.next_due);
  if (!pd.ok) { push('error', 'DATE_PARSE_FAILED', ''); continue; }
  if (isYes(r.deal_shared) && !isYes(r.fu3_done) && !pd.val) { push('error', 'NEXT_DUE_MISSING', ''); continue; }
  if (!isYes(r.fu1_done) && due(pd.val)) { push('send', 'fu1', 'FU1'); continue; }
  if (!isYes(r.fu2_done) && due(pd.val)) { push('send', 'fu2', 'FU2'); continue; }
  if (!isYes(r.fu3_done) && due(pd.val)) { push('send', 'fu3', 'FU3'); continue; }
  if (isYes(r.fu3_done)) { push('skip', 'fu3-complete', ''); continue; }
  push('skip', 'nothing-due', '');
}
return out;

const cfg = $('Build CONFIG object').first().json;
const OWNER = cfg.OWNER_NAME;
const tz = cfg.TIMEZONE || 'Asia/Kolkata';
const today = DateTime.now().setZone(tz).toISODate();
const totalCap = parseInt(cfg.DAILY_TOTAL_CAP, 10) || 50;
const newCap = parseInt(cfg.DAILY_NEW_SENDS, 10) || 25;

let sentToday = 0;
for (const p of $('Read PIPELINE').all()) {
  const row = p.json;
  if (String(row.owner).trim() === OWNER && String(row.last_contact).trim() === today) sentToday++;
}

const followups = [];
const initials = [];
for (const it of $input.all()) {
  if (it.json.action !== 'send') continue;
  if (it.json.stage === 'INITIAL') initials.push(it); else followups.push(it);
}

// PRIORITY rows (notes contain 'PRIORITY', e.g. Train Rex push 18 Sep) take the new-send slots first; order is otherwise unchanged.
const PRI = {};
for (const p of $('Read PIPELINE').all()) { if (/PRIORITY/.test(String(p.json.notes || ''))) PRI[String(p.json.deal_id).trim()] = 1; }
// HOT deals (user 22 Sep, Q4 close push) also go first - new shares AND follow-ups.
const HOT = ['spintly', 'boncuisine', 'eosnox', 'hyrgpt', 'talentrecruit', 'hoora', 'clikd', 'mindwox', 'mentorcloud', 'roadathena', 'learningpad'];
for (const p of $('Read PIPELINE').all()) { if (HOT.indexOf(String(p.json.startup || '').toLowerCase().replace(/[^a-z0-9]/g, '')) >= 0) PRI[String(p.json.deal_id).trim()] = 1; }
initials.sort((a, b) => (PRI[String(b.json.deal_id).trim()] ? 1 : 0) - (PRI[String(a.json.deal_id).trim()] ? 1 : 0));
followups.sort((a, b) => (PRI[String(b.json.deal_id).trim()] ? 1 : 0) - (PRI[String(a.json.deal_id).trim()] ? 1 : 0));

let totalRemaining = totalCap - sentToday;
if (totalRemaining < 0) totalRemaining = 0;

// New deals claim their slots first (bounded by DAILY_NEW_SENDS), then follow-ups take the rest.
const pickNew = [];
let newRemaining = newCap;
for (const n of initials) {
  if (totalRemaining <= 0 || newRemaining <= 0) break;
  pickNew.push(n); totalRemaining--; newRemaining--;
}
const pickFu = [];
for (const f of followups) {
  if (totalRemaining <= 0) break;
  pickFu.push(f); totalRemaining--;
}

// Interleave proportionally so neither kind sits at the tail: if a run is cut short
// it loses a slice of both, not every new deal (see 11/14/15 Sep 2026).
const out = [];
const nN = pickNew.length, nF = pickFu.length;
let ai = 0, bi = 0;
while (ai < nN || bi < nF) {
  if (ai < nN && (bi >= nF || ai * nF <= bi * nN)) { out.push(pickNew[ai++]); }
  else { out.push(pickFu[bi++]); }
}
return out;

const staticData = $getWorkflowStaticData('global');
const log = Array.isArray(staticData.runLog) ? staticData.runLog : [];
const cfg = $('Build CONFIG object').first().json;
const tz = cfg.TIMEZONE || 'Asia/Kolkata';
const today = DateTime.now().setZone(tz).toISODate();

let sends = 0;
for (const l of log) { if (String(l.result).indexOf('SEND ') === 0) sends++; }

const decided = $('Decide ONE action per row').all();
const rowsRead = $('Read PIPELINE').all().length;

const skipCounts = {};
let skipped = 0;
for (const d of decided) {
  if (d.json.action === 'skip') { skipped++; const rsn = d.json.reason || 'unknown'; skipCounts[rsn] = (skipCounts[rsn] || 0) + 1; }
}
for (const l of log) {
  if (l.result === 'SKIP investor-locked-this-run') { skipped++; skipCounts['investor-locked-this-run'] = (skipCounts['investor-locked-this-run'] || 0) + 1; }
  else if (l.result === 'SKIP investor-locked-sheet') { skipped++; skipCounts['investor-locked-sheet'] = (skipCounts['investor-locked-sheet'] || 0) + 1; }
}
const skipReasons = Object.keys(skipCounts).map((k) => k + ':' + skipCounts[k]).join(', ');

return [{ json: {
  date: today,
  workflow: 'D',
  rows_read: rowsRead,
  decided: decided.length,
  sent: sends,
  skipped: skipped,
  skip_reasons: skipReasons,
} }];

const cfg = $('Build CONFIG object').first().json;
const tz = cfg.TIMEZONE || 'Asia/Kolkata';
const parsedLock = parseInt(cfg.INVESTOR_LOCK_DAYS, 10);
const lockDays = isNaN(parsedLock) ? 7 : parsedLock;
const today = DateTime.now().setZone(tz);

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.contactedThisRun)) staticData.contactedThisRun = [];
if (!Array.isArray(staticData.runLog)) staticData.runLog = [];

const r = $json;
const investorName = String(r.investor).trim();
const blank = (x) => x === undefined || x === null || String(x).trim() === '';
const isoRe = /^\d{4}-\d{2}-\d{2}$/;

let inv = null;
for (const v of $('Read INVESTORS').all()) { if (String(v.json.investor).trim() === investorName) { inv = v.json; break; } }

if (lockDays > 0) {
  if (staticData.contactedThisRun.indexOf(investorName) !== -1) {
    staticData.runLog.push({ deal_id: r.deal_id, result: 'SKIP investor-locked-this-run', investor: investorName });
    return { json: Object.assign({}, r, { would_send: false, skip_reason: 'investor-locked-this-run' }) };
  }
  if (inv && !blank(inv.last_contacted_any) && isoRe.test(String(inv.last_contacted_any).trim())) {
    const d = DateTime.fromISO(String(inv.last_contacted_any).trim(), { zone: tz });
    if (d.isValid) {
      const diff = today.startOf('day').diff(d.startOf('day'), 'days').days;
      if (diff < lockDays) {
        staticData.runLog.push({ deal_id: r.deal_id, result: 'SKIP investor-locked-sheet', investor: investorName });
        return { json: Object.assign({}, r, { would_send: false, skip_reason: 'investor-locked-sheet', locked_since: String(inv.last_contacted_any).trim() }) };
      }
    }
  }
}
return { json: Object.assign({}, r, { would_send: true }) };

const cfg = $('Build CONFIG object').first().json;
const r = $json;
const stage = r.stage; // INITIAL | FU1 | FU2 | FU3

let st = null;
for (const s of $('Read STARTUPS').all()) { if (String(s.json.startup).trim() === String(r.startup).trim()) { st = s.json; break; } }
let inv = null;
for (const v of $('Read INVESTORS').all()) { if (String(v.json.investor).trim() === String(r.investor).trim()) { inv = v.json; break; } }

// ROUTING rows get the routing variant of the INITIAL template only; follow-ups stay on FU1/FU2/FU3.
const isRouting = String(r.channel || '').toUpperCase() === 'ROUTING';
const tid = (stage === 'INITIAL' && isRouting) ? 'INITIAL_ROUTING' : stage;

let tpl = null;
for (const t of $('Read TEMPLATES').all()) { if (String(t.json.template_id).trim() === tid) { tpl = t.json; break; } }
if (!tpl) throw new Error('Template not found for stage ' + tid);

const tokens = {
  '{{InvestorName}}': inv.investor,
  '{{ContactPerson}}': inv.contact_person,
  '{{StartupName}}': st.startup,
  '{{Sector}}': st.sector,
  '{{FundraiseAmount}}': st.raise_inr_cr,
  '{{Revenue}}': st.revenue,
  '{{Highlight1}}': st.highlight_1,
  '{{Highlight2}}': st.highlight_2,
  '{{Highlight3}}': st.highlight_3,
  '{{DeckLink}}': st.deck_link,
  '{{SenderName}}': cfg.SENDER_NAME,
};
const fill = (s) => {
  let out = String(s == null ? '' : s);
  for (const k in tokens) { out = out.split(k).join(String(tokens[k] == null ? '' : tokens[k])); }
  return out;
};
let subject = fill(tpl.subject);
const body0 = fill(tpl.body);
let memoHtml = (st.memo_html == null ? '' : String(st.memo_html));

// ---- RAISE REMOVAL (user rules 2026-09-15 and 2026-09-16) ----
// (a) pre-revenue startups: the raise is removed from subject + memo for EVERY investor type (from 17 Sep).
// (b) 13 angels x 27 startups: additionally strips pre-revenue wording and other companies' funding lines.
// Applied at SEND TIME only; the memo stored in STARTUPS is never modified.
// Removes text only and keeps every HTML tag so the layout survives. Never throws: if the cleaner errors,
// unbalances tags or still finds raise text, the memo falls back to name + sector + highlights.
// 1 Oct 2026: ServeAmigo REMOVED from the list (was 16, now 15). Aditya: "serve amigo message me they booked 5 lakhs
// reveneu in september so they are not pre reveneu anymore... fix serve amigo with raise amount".
// It booked INR 5 lakh in Sep 2026, so STARTUPS/STARTUP_PROFILE now read Early Revenue and it must show its ask again.
// Dropping it from _ALL16 also drops it from _HIDE27, which is correct: angels should see the raise too now.
const _nz = function (x) { return String(x == null ? '' : x).toLowerCase().replace(/[^a-z0-9]/g, ''); };
const _ANGELS = {};
['Gautam Kapur','Ignacio','Ishan Singh','Jonathan Solamon','Alex Alpert','Devesh','Mandeep Singh','Ankit','Vivasvan','Mohit','Gautham Krishnan','Sayan Ghosh','Michele'].forEach(function (x) { _ANGELS[_nz(x)] = 1; });
const _ALL16 = {};
['Body & Beyond','Outlanders','Koncite','Washtro','Fire Armor','Tronix.AI','Springbase.ai','Formverse','MonitorExam','Pixelence','Fuski.AI','Vilva AI','SkillBytes','Orbit AI','Vira Jal'].forEach(function (x) { _ALL16[_nz(x)] = 1; });
const _HIDE27 = Object.assign({}, _ALL16);
['Opulytics','Train Rex','Xproguard','Indie Stori','Appli','Luxova','AI Signal Labs','Desi Machines','Doffair','bezgoFresh','Chayan Karo'].forEach(function (x) { _HIDE27[_nz(x)] = 1; });
const _mode = (_ANGELS[_nz(inv.investor)] && _HIDE27[_nz(st.startup)]) ? 'angel' : (_ALL16[_nz(st.startup)] ? 'all' : '');
if (_mode) {
  let _R = null;
  try { _R = (function () {
const AMT = String.raw`(?:(?:₹|\brs\.?|\binr|\busd|us\$|\$|€|\beur|£)\s*\d[\d.,]*(?:\s*(?:cr\b|crores?\b|lakhs?\b|lacs?\b|l\b|mn\b|m\b|million\b|k\b|bn\b|billion\b))?|\d[\d.,]*\s*(?:cr\b|crores?\b|lakhs?\b|lacs?\b|mn\b|million\b|bn\b|billion\b)|\d[\d.,]*(?:m|k|l)\b)`;
const KW = String.raw`(?:\brais(?:e|es|ing)\b|\bfund\s*-?\s*rais(?:e|es|ing)\b|\bfundrais(?:e|es|ing)\b|\b(?:fund|funds|funding|investment|capital)\s*(?:ask|sought|required|requirement|needed)\b|\bthe\s+ask\b|\bask\s*[:\-–—]|\basking\s+for\b|\bseeking\b|\b(?:round|raise|ticket|cheque|check)\s*size\b|\bminimum\s+(?:ticket|cheque|check)\b|\b(?:current|this|proposed|ongoing)\s+round\b)`;
const AMT1 = new RegExp(AMT, 'i');
const OWN_A = new RegExp(KW + '[^.<|]{0,60}?' + AMT, 'i');
const OWN_B = /(?:\brais(?:e|es|ing)\b|\bfund(?:ing)?\s*ask\b)[^.<|]{0,15}?\d/i;
const AMT_ROUND = new RegExp(AMT + String.raw`[^.<|]{0,30}?\b(?:round|raise|fundraise|ask)\b`, 'i');
const CTX_B = new RegExp(String.raw`\b(?:raised|raises|secured|closed|bagged|landed)\b[^.<|]{0,60}?` + AMT, 'i');
const RAISEREF = /\b(?:the|this|our)\s+raise\s+(?:is|will|would)\b|\b(?:funding|funds|capital|proceeds)\s+(?:raised\s+)?(?:will|would|shall)\s+be\s+(?:used|deployed|allocated|utili[sz]ed)\b|\buse\s+of\s+(?:funds|proceeds)\b|\b(?:this|the\s+current)\s+round\s+is\s+(?:intended|meant|designed)\b/i;
const PAST = /\braised\b|\bclosed\b|\bsecured\b|\bled by\b|\bbacked by\b|\bfunded by\b/i;
const PRE = /pre-?\s*revenue|pre-?\s*launch|pre-?\s*monetis|pre-?\s*monetiz/i;
const HEAD = /^(?:the\s+)?(?:funding\s+ask|fund\s*ask|ask|investment\s+ask|fundrais(?:e|ing)(?:\s+details)?|funding\s+round|current\s+round|round(?:\s+details|\s+size)?|raise|raising|deal\s+terms)\s*[:\-–—]?$/i;
const URLISH = /https?:\/\/|www\.|^\s*(?:website|web|site|press|linkedin)\s*:/i;
const ROUNDLINE = /runway|valuation|pre-?money|post-?money|deployment|use\s+of\s+(?:funds|proceeds)|allocation|dilution|\bsafe\b|convertible|instrument|ticket|cheque|\bround\b|\braise\b|\braising\b/i;
const PAREN = /\s*\([^()]*pre-?\s*(?:revenue|launch|monetis|monetiz)[^()]*\)/i;
const SPLIT_SRC = String.raw`(?<=[.!?])(?<!\b(?:Rs|RS|rs|No|no|vs|Vs|Pvt|PVT|Ltd|LTD|Inc|approx|Approx|Dr|Mr|Ms|Mrs|St|Co|etc|e\.g|i\.e)\.)\s+(?=[^a-z\s])`;
const BLOCKTAG = /^<\/?(?:div|p|li|ul|ol|h[1-6]|table|tbody|thead|tr|td|th|section|blockquote|hr|br)\b/i;
const ENT = {nbsp:' ',amp:'&',bull:'•',rsquo:'’',lsquo:'‘',rdquo:'”',ldquo:'“',quot:'“',apos:'’',mdash:'—',ndash:'–',hellip:'…',lt:'‹',gt:'›',middot:'·',rarr:'→',times:'×',deg:'°',trade:'™',reg:'®',copy:'©',euro:'€',pound:'£',rupee:'₹'};
function classify(x) { if (OWN_A.test(x) || OWN_B.test(x) || RAISEREF.test(x)) { return 'own'; } if (AMT_ROUND.test(x)) { return PAST.test(x) ? 'context' : 'own'; } if (CTX_B.test(x)) { return 'context'; } return null; }
function kill(x, mode) { const c = classify(x); if (c === 'own') { return true; } return mode === 'angel' && (c === 'context' || PRE.test(x)); }
function build(html) { const P = [], S = [], E = []; const n = html.length; let i = 0;
 while (i < n) { const ch = html[i];
  if (ch === '<') { const j = html.indexOf('>', i); if (j >= 0) { if (BLOCKTAG.test(html.slice(i, j + 1))) { P.push('\n'); S.push(i); E.push(j + 1); } i = j + 1; continue; } }
  if (ch === '&') { const m = /^&(#\d{1,7}|#x[0-9a-f]{1,6}|[a-z]{2,10});/i.exec(html.slice(i, i + 14)); if (m) { const k = m[1]; let d; if (k[0] === '#') { const cp = (k[1] === 'x' || k[1] === 'X') ? parseInt(k.slice(2), 16) : parseInt(k.slice(1), 10); try { d = String.fromCodePoint(cp); } catch (e) { d = ' '; } } else { d = ENT[k.toLowerCase()]; if (d === undefined) { d = ' '; } } for (let q = 0; q < d.length; q++) { P.push(d[q]); S.push(i); E.push(i + m[0].length); } i += m[0].length; continue; } }
  P.push(/\s/.test(ch) ? ' ' : ch); S.push(i); E.push(i + 1); i++; }
 return { t: P.join(''), S: S, E: E }; }
function lines(t) { const out = []; let ls = 0;
 for (let k = 0; k <= t.length; k++) { if (k === t.length || t[k] === '\n') { if (k > ls) { out.push({ s: ls, e: k }); } ls = k + 1; } }
 for (const L of out) { L.segs = []; const lt = t.slice(L.s, L.e); const re = /\s*\|\s*/g; let last = 0, m;
  while ((m = re.exec(lt)) !== null) { L.segs.push({ s: L.s + last, e: L.s + m.index, sepEnd: L.s + m.index + m[0].length }); last = m.index + m[0].length; }
  L.segs.push({ s: L.s + last, e: L.e, sepEnd: L.e });
  for (const G of L.segs) { G.sents = []; const gt = t.slice(G.s, G.e); const sp = new RegExp(SPLIT_SRC, 'g'); let p = 0, x;
   while ((x = sp.exec(gt)) !== null) { G.sents.push({ s: G.s + p, e: G.s + x.index, next: G.s + x.index + x[0].length }); p = x.index + x[0].length; }
   G.sents.push({ s: G.s + p, e: G.e, next: G.e }); } }
 return out; }
function headingLike(x) { return x.length <= 40 && /[a-z]/i.test(x) && !/[.!?;,|]/.test(x) && !/:\s*\S/.test(x) && !AMT1.test(x); }
function analyse(html, mode) { const B = build(html); const t = B.t; const L = lines(t); const removed = []; const R = [];
 const lt = L.map(function (o) { return t.slice(o.s, o.e).trim(); });
 const gone = L.map(function () { return false; });
 const heads = [];
 for (let a = 0; a < L.length; a++) { if (!lt[a] || !HEAD.test(lt[a])) { continue; } const sect = [];
  for (let b = a + 1; b < L.length; b++) { if (!lt[b]) { continue; } if (headingLike(lt[b])) { break; } sect.push(b); }
  heads.push({ a: a, sect: sect });
  for (const c of sect) { if (URLISH.test(lt[c])) { continue; } if (AMT1.test(lt[c]) || ROUNDLINE.test(lt[c])) { gone[c] = true; removed.push(lt[a] + ' => ' + lt[c].slice(0, 200)); } } }
 for (let a = 0; a < L.length; a++) { if (!lt[a] || gone[a]) { continue; } const segs = L[a].segs; let any = false;
  for (const G of segs) { let hasText = false, allKill = true;
   for (const X of G.sents) { const raw = t.slice(X.s, X.e); const x = raw.trim(); if (!x) { continue; } hasText = true;
    if (!kill(x, mode)) { allKill = false; continue; }
