  var x = String(s == null ? '' : s).replace(/&mdash;/gi, '—').replace(/&ndash;/gi, '–');
  x = x.replace(/\s+[–—]\s+/g, ', ');
  x = x.replace(/[–—]/g, '-');
  return x;
};
subject = _dashFix(subject);
const bodyND = _dashFix(body);
const htmlND = _dashFix(html);
const _BAD = /[–—]|&mdash;|&ndash;/i;
if (_BAD.test(subject) || _BAD.test(htmlND)) {
  throw new Error('DASH FOUND IN OUTBOUND EMAIL after cleaning, refusing to send. deal ' + r.deal_id);
}

return { json: Object.assign({}, r, {
  to: r.email,
  cc: r.cc || '',
  subject,
  body: bodyND,
  html: htmlND,
  threadId: r.thread_id || '',
  replyMessageId: r.message_id || '',
}) };

const cfg = $('Build CONFIG object').first().json;
const tz = cfg.TIMEZONE || 'Asia/Kolkata';
const now = DateTime.now().setZone(tz);
const today = now.toISODate();
const fu1 = parseInt(cfg.FU1_DAYS, 10); const FU1 = isNaN(fu1) ? 4 : fu1;
const fu2 = parseInt(cfg.FU2_DAYS, 10); const FU2 = isNaN(fu2) ? 7 : fu2;
const fu3 = parseInt(cfg.FU3_DAYS, 10); const FU3 = isNaN(fu3) ? 9 : fu3;

const resp = $json;
const be = $('Build email').item.json;
const stage = be.stage;
const gmailId = resp.id || '';
const gmailThread = resp.threadId || '';

const row = { deal_id: be.deal_id, last_contact: today };
if (stage === 'INITIAL') {
  row.deal_shared = 'Yes';
  row.date_shared = today;
  row.channel = 'Email';
  row.thread_id = gmailThread;
  row.message_id = gmailId;
  row.next_action = 'Follow-up 1';
  row.next_due = now.plus({ days: FU1 }).toISODate();
} else if (stage === 'FU1') {
  row.fu1_done = 'Yes';
  row.fu1_date = today;
  row.next_action = 'Follow-up 2';
  row.next_due = now.plus({ days: FU2 }).toISODate();
} else if (stage === 'FU2') {
  row.fu2_done = 'Yes';
  row.fu2_date = today;
  row.next_action = 'Follow-up 3';
  row.next_due = now.plus({ days: FU3 }).toISODate();
} else if (stage === 'FU3') {
  row.fu3_done = 'Yes';
  row.fu3_date = today;
  row.next_action = 'Await investor revert';
  row.next_due = '';
}

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.runLog)) staticData.runLog = [];
staticData.runLog.push({ deal_id: be.deal_id, result: 'SEND ' + stage, investor: be.investor, startup: be.startup });
// Claim the within-run investor lock AFTER a successful send (2.7).
if (!Array.isArray(staticData.contactedThisRun)) staticData.contactedThisRun = [];
const investorName = String(be.investor).trim();
if (staticData.contactedThisRun.indexOf(investorName) === -1) staticData.contactedThisRun.push(investorName);

return { json: row };

