const cfg = $('Build CONFIG object').first().json;
const tz = cfg.TIMEZONE || 'Asia/Kolkata';
const today = DateTime.now().setZone(tz).toISODate();
const wf = 'D';

const existing = {};
for (const e of $('Read ERROR LOG').all()) {
  const j = e.json;
  if (String(j.resolved || '').trim() !== '') continue;
  existing[String(j.deal_id).trim() + '|' + String(j.error_type).trim()] = true;
}

const seen = {};
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (j.action !== 'error') continue;
  const key = String(j.deal_id).trim() + '|' + String(j.reason).trim();
  if (existing[key] || seen[key]) continue;
  seen[key] = true;
  out.push({ json: {
    timestamp: today,
    workflow: wf,
    deal_id: j.deal_id,
    startup: j.startup,
    investor: j.investor,
    error_type: j.reason,
    details: 'Decision-stage error: ' + j.reason,
    resolved: '',
  }});
}
return out;

// One row per send, for the `shares` table. Added 30 Sep 2026.
// Parallel to the PIPELINE write-back; every node continues on error so a
// Supabase problem can never break a send.
const be = $('Build email').item.json;
const cfg = $('Build CONFIG object').first().json;
const stage = String(be.stage || '');
const fuNo = stage === 'FU1' ? 1 : (stage === 'FU2' ? 2 : (stage === 'FU3' ? 3 : null));

// `Decide ONE action per row` builds a whitelist `base` object that omits
// match_type, so it never reaches Build email. Read it back from the PIPELINE
// row by deal_id rather than widening that node on four live senders.
let raw = '';
try {
  const did = String(be.deal_id || '').trim();
  for (const p of $('Read PIPELINE').all()) {
    if (String(p.json.deal_id || '').trim() === did) { raw = String(p.json.match_type || ''); break; }
  }
} catch (e) { raw = ''; }

// The sheet holds prose, not enum codes. Order matters: the stage-off label
// also contains the word sector, so it has to be tested first.
let type = null;
if (/stage\s+(?:one\s+step\s+)?off/i.test(raw)) { type = 'stage_off'; }
else if (/^\s*exact\s+match/i.test(raw)) { type = 'strict'; }
else if (/sector\s*\+\s*cheque\s+match/i.test(raw)) { type = 'sector_only'; }
else if (/minimum\s+cheque|fails\s+cheque/i.test(raw)) { type = 'below_min_cheque'; }

return { json: {
  startup: String(be.startup || '').trim(),
  investor: String(be.investor || '').trim(),
  mailbox: String(cfg.SENDER_NAME || '').trim() || null,
  type: type,
  match_type_raw: raw,
  is_followup: stage !== 'INITIAL',
  followup_no: fuNo
} };
